// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker attacker;
    address other;

    function setUp() public {
        c = new ReentrancyDAO();
        other = address(0xBEEF);
        attacker = new Attacker(c, other);
    }

    function testFuzz_property(uint256 amtA, uint256 amtB) public {
        amtA = bound(amtA, 1, 1e18);
        amtB = bound(amtB, 1, 1e18);

        // second depositor funds their credit
        vm.deal(other, amtB);
        vm.prank(other);
        c.deposit{value: amtB}();

        // attacker deposits its fuzzed credit
        vm.deal(address(attacker), amtA);
        attacker.deposit{value: amtA}();

        // padding so every payout can succeed when the guard is absent
        vm.deal(address(c), 5e18);

        bool ok;
        try attacker.pull() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: reentrancy lock blocks the inner withdrawAll, the inner
        // call fails and the outer withdrawAll reverts.  Mutant: lock never
        // set, inner call succeeds, whole call completes.
        assertTrue(!ok);
    }
}

contract Attacker {
    ReentrancyDAO c;
    address other;

    constructor(ReentrancyDAO _c, address _o) {
        c = _c;
        other = _o;
    }

    function deposit() external payable {
        c.deposit{value: msg.value}();
    }

    function pull() external {
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter on behalf of the other depositor
        (bool okVm, ) = 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D.call(
            abi.encodeWithSignature("prank(address)", other)
        );
        require(okVm);
        c.withdrawAll();
    }
}
